SELECT analytics_order_facts.payment_method, COUNT(DISTINCT analytics_order_facts.active_customer_id) AS active_customer_count FROM analytics_order_facts WHERE analytics_order_facts.year = 2026 AND analytics_order_facts.month = 12 AND analytics_order_facts.region = 'East' AND analytics_order_facts.channel = 'marketplace' AND analytics_order_facts.customer_segment = 'public' GROUP BY analytics_order_facts.payment_method ORDER BY active_customer_count DESC, analytics_order_facts.payment_method ASC LIMIT 12
